{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    # Validate segments have required fields
    for i, seg in enumerate(segments):
        if not isinstance(seg, dict):
            raise ValueError('Each segment must be a dict')
        for key in ('name', 'importance', 'minimum', 'capacity'):
            if key not in seg:
                raise ValueError(f'Segment {i} missing key {key}')
        try:
            seg['importance'] = int(seg['importance'])
            seg['minimum'] = int(seg['minimum'])
            seg['capacity'] = int(seg['capacity'])
        except (ValueError, TypeError):
            raise ValueError(f'Segment {i} has non-integer numeric field')
        if seg['minimum'] < 0 or seg['capacity'] < seg['minimum']:
            raise ValueError(f'Segment {i} has invalid minimum/capacity')
    min_sum = sum(s['minimum'] for s in segments)
    max_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum:
        raise ValueError(f'Budget {budget} below total minimum {min_sum}')
    if budget > max_sum:
        raise ValueError(f'Budget {budget} exceeds total capacity {max_sum}')
    # Initialize allocations at minimum
    n = len(segments)
    alloc = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    # Allocate remaining tokens one by one
    while remaining > 0:
        best_idx = -1
        best_val = -1.0
        for i in range(n):
            if alloc[i] >= segments[i]['capacity']:
                continue
            pos = alloc[i] + 1
            metric = segments[i]['importance'] / pos
            if metric > best_val + 1e-12:
                best_val = metric
                best_idx = i
            elif abs(metric - best_val) < 1e-12 and i < best_idx:
                # tie: keep earlier index (original order)
                pass
        if best_idx == -1:
            # Should not happen as budget <= max_sum, but safety
            remaining = 0
            break
        alloc[best_idx] += 1
        remaining -= 1
    # Build result
    allocations = []
    name_mapping = {}
    total = 0
    for i, seg in enumerate(segments):
        name = seg['name']
        amt = alloc[i]
        allocations.append({'name': name, 'allocated': amt})
        name_mapping[name] = amt
        total += amt
    return {
        'allocations': allocations,
        'name_mapping': name_mapping,
        'total_allocated': total
    }
